1	package com.example.starter;
2	
3	import java.util.List;
4	import java.util.concurrent.Callable;
5	import java.util.concurrent.CountDownLatch;
6	import java.util.concurrent.ExecutorService;
7	import java.util.concurrent.Executors;
8	import java.util.concurrent.Future;
9	import java.util.concurrent.TimeUnit;
10	
11	import com.example.starter.dto.GrainDtos.FanView;
12	import com.example.starter.dto.GrainDtos.JobView;
13	import com.example.starter.dto.GrainDtos.SiloView;
14	import com.example.starter.error.ApiException;
15	import com.example.starter.model.SiloStatus;
16	
17	import org.junit.jupiter.api.Test;
18	
19	import static org.junit.jupiter.api.Assertions.assertEquals;
20	import static org.junit.jupiter.api.Assertions.assertTrue;
21	
22	/**
23	 * 并发测试：同一仓并发下达唯一受理；同一风机并发争抢只服务一个仓。
24	 * 通过门闩协调真实并发，断言最终结果与数据库状态，并设置超时。
25	 */
26	class VentilationConcurrencyTest extends AbstractIntegrationTest {
27	
28	    @Test
29	    void concurrentJobsOnSameSiloOnlyOneAccepted() throws Exception {
30	        SiloView silo = newSilo("S-CC");
31	        FanView fan1 = newFan("F-CC1");
32	        FanView fan2 = newFan("F-CC2");
33	        raiseAlarm(silo.id(), "r-cc-alarm");
34	
35	        List<Outcome> outcomes = runConcurrently(
36	                () -> capture(() -> ventilationService.createJob(silo.id(), newJobRequest("j-cc-1", fan1.id()))),
37	                () -> capture(() -> ventilationService.createJob(silo.id(), newJobRequest("j-cc-2", fan2.id()))));
38	
39	        long accepted = outcomes.stream().filter(o -> o.error() == null).count();
40	        long rejected = outcomes.stream()
41	                .filter(o -> o.error() != null && "JOB_ALREADY_EXECUTING".equals(o.error().getCode()))
42	                .count();
43	        assertEquals(1, accepted, "并发下达只能唯一受理");
44	        assertEquals(1, rejected, "另一个并发请求应以 409 拒绝");
45	        assertEquals(1, countRows("ventilation_job"));
46	        assertEquals(SiloStatus.VENTILATING, siloService.getSilo(silo.id()).status());
47	    }
48	
49	    @Test
50	    void concurrentFanContentionLocksExactlyOneJob() throws Exception {
51	        SiloView siloA = newSilo("S-FCA");
52	        SiloView siloB = newSilo("S-FCB");
53	        FanView fan = newFan("F-CONT");
54	        raiseAlarm(siloA.id(), "r-fca-alarm");
55	        raiseAlarm(siloB.id(), "r-fcb-alarm");
56	
57	        List<Outcome> outcomes = runConcurrently(
58	                () -> capture(() -> ventilationService.createJob(siloA.id(), newJobRequest("j-fc-1", fan.id()))),
59	                () -> capture(() -> ventilationService.createJob(siloB.id(), newJobRequest("j-fc-2", fan.id()))));
60	
61	        long accepted = outcomes.stream().filter(o -> o.error() == null).count();
62	        long fanBusy = outcomes.stream()
63	                .filter(o -> o.error() != null && "FAN_BUSY".equals(o.error().getCode()))
64	                .count();
65	        assertEquals(1, accepted, "同一台风机同一时刻只服务一个仓");
66	        assertEquals(1, fanBusy, "落选请求应以 FAN_BUSY 拒绝");
67	
68	        // 锁定原子性：只有一个作业开始，且风机确实锁定到该作业；落选仓无作业、状态未变
69	        assertEquals(1, countRows("ventilation_job"));
70	        FanView locked = siloService.getFan(fan.id());
71	        assertEquals("LOCKED", locked.status());
72	        JobView winner = ventilationService.windows(siloA.id()).stream().findFirst()
73	                .orElseGet(() -> ventilationService.windows(siloB.id()).get(0));
74	        assertEquals(winner.id(), locked.lockedJobId());
75	        long loserSiloId = winner.siloId() == siloA.id() ? siloB.id() : siloA.id();
76	        assertEquals(SiloStatus.ALARMING, siloService.getSilo(loserSiloId).status());
77	    }
78	
79	    private List<Outcome> runConcurrently(Callable<Outcome> first, Callable<Outcome> second) throws Exception {
80	        ExecutorService pool = Executors.newFixedThreadPool(2);
81	        CountDownLatch gate = new CountDownLatch(1);
82	        try {
83	            Future<Outcome> f1 = pool.submit(() -> {
84	                gate.await();
85	                return first.call();
86	            });
87	            Future<Outcome> f2 = pool.submit(() -> {
88	                gate.await();
89	                return second.call();
90	            });
91	            gate.countDown();
92	            return List.of(f1.get(15, TimeUnit.SECONDS), f2.get(15, TimeUnit.SECONDS));
93	        } finally {
94	            pool.shutdownNow();
95	            assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS));
96	        }
97	    }
98	
99	    private Outcome capture(Callable<JobView> call) {
100	        try {
101	            return new Outcome(call.call(), null);
102	        } catch (ApiException ex) {
103	            return new Outcome(null, ex);
104	        } catch (Exception ex) {
105	            throw new IllegalStateException("并发用例出现非业务异常", ex);
106	        }
