 */
@SpringBootTest
@ActiveProfiles("test")
public abstract class AbstractIntegrationTest {

    protected static final LocalDateTime T0 = LocalDateTime.of(2026, 9, 26, 8, 0);

    @Autowired
    protected JdbcTemplate jdbc;

    @Autowired
    protected SiloService siloService;

    @Autowired
